import React from "react";
import { useNavigate } from "react-router-dom";

const cardGroups = [
  {
    title: "Up to 60% off | Curated kitchen products",
    images: [
      "https://m.media-amazon.com/images/I/61dU3TSFm9L._SX679_.jpg",
      "https://m.media-amazon.com/images/I/71wZ2W0dcFL._SL1500_.jpg",
      "https://m.media-amazon.com/images/I/71qjUzq-sFL._SL1500_.jpg",
      "https://m.media-amazon.com/images/I/61g0U4owg3L._SL1500_.jpg",
    ],
    mainImage: "https://m.media-amazon.com/images/I/61dU3TSFm9L._SX679_.jpg",
    price: "₹1,299.00",
    mrp: "₹1,999.00",
  },
  {
    title: "Customers’ Most-Loved Fashion for you",
    images: [
      "https://m.media-amazon.com/images/I/61M-B24RkkL._UX679_.jpg",
      "https://m.media-amazon.com/images/I/81X7G5LGQKL._UX679_.jpg",
      "https://m.media-amazon.com/images/I/71eUwDk8z+L._UX679_.jpg",
      "https://m.media-amazon.com/images/I/71P1GClQYML._UY741_.jpg",
    ],
    explore: true,
  },
  {
    title: "Best Sellers in Computers & Accessories",
    images: [
      "https://m.media-amazon.com/images/I/61HT48Y-1aL._SL1500_.jpg",
      "https://m.media-amazon.com/images/I/71RItT+qqbL._SL1500_.jpg",
      "https://m.media-amazon.com/images/I/71SGYyTvr1L._SL1500_.jpg",
      "https://m.media-amazon.com/images/I/61GDKcU50sL._SL1500_.jpg",
    ],
  },
  {
    title: "Top picks & best offers from Small Businesses",
    images: [
      "https://m.media-amazon.com/images/I/41nsn0i1MzL.jpg",
      "https://m.media-amazon.com/images/I/71bUkmrzV+L._SX679_.jpg",
      "https://m.media-amazon.com/images/I/61TQfpn9WCL._SL1500_.jpg",
      "https://m.media-amazon.com/images/I/41A7Z3n1a9L.jpg",
    ],
    mainImage: "https://m.media-amazon.com/images/I/41nsn0i1MzL.jpg",
    price: "₹1,349.00",
    mrp: "₹2,200.00",
  },
];

const AdPage = () => {
  const navigate = useNavigate();

  return (
    <div className="adpage-container">
      {/* Banner */}
      <div className="banner">
        <img
          src="https://m.media-amazon.com/images/I/71nwqPZaNRL._SX3000_.jpg"
          alt="Main Banner"
        />
      </div>

      {/* Cards like Amazon Home */}
      <div className="grid-container">
        {cardGroups.map((group, index) => (
          <div className="product-block" key={index} onClick={() => navigate("/products")}>
            <h3>{group.title}</h3>
            <div className="main-img">
              {group.mainImage && <img src={group.mainImage} alt="main" />}
            </div>
            {group.price && (
              <p className="price">
                <strong>{group.price}</strong> <span className="mrp">M.R.P: <del>{group.mrp}</del></span>
              </p>
            )}
            <div className="mini-thumbs">
              {group.images.map((img, i) => (
                <img src={img} key={i} alt={`thumb-${i}`} />
              ))}
            </div>
            {group.explore && <a href="/products" className="explore-link">Explore more</a>}
          </div>
        ))}
      </div>
    </div>
  );
};

export default AdPage;
